svg.script:
(() => {
  const svg = document.currentScript.ownerSVGElement;
  const objects = [...svg.querySelectorAll('.interactive-object')];

  const emit = (object, active) => {
    svg.dispatchEvent(new CustomEvent('campus-object-hover', {
      bubbles: true,
      detail: {
        active,
        id: object.id,
        index: Number(object.dataset.objectIndex),
        type: object.dataset.objectType || '',
        title: object.dataset.title || object.id,
        description: object.dataset.description || ''
      }
    }));
  };

  objects.forEach((object) => {
    object.addEventListener('pointerenter', () => emit(object, true));
    object.addEventListener('pointerleave', () => emit(object, false));
    object.addEventListener('focus', () => emit(object, true));
    object.addEventListener('blur', () => emit(object, false));
  });
})();
